//! `--expect-region-contains` against an `h3_polygon_set` region, checked
//! against golden vectors.
//!
//! `test-vectors/h3-containment/vectors.json` is generated by `generate.py` with
//! the reference H3 C library, while the verifier evaluates containment with the
//! pure-Rust `h3o`. Agreement on every vector is a cross-implementation check,
//! not a self-check. Cases: in-cell, out-of-cell, mixed and compacted
//! resolutions, a pentagon, a shared boundary vertex, duplicates, and the
//! fail-closed malformed sets (empty, invalid index, edge index, one invalid
//! index next to a valid hit).
//!
//! With the `h3` feature each vector must match its `expect`. Without it, every
//! vector must FAIL: the lean build cannot evaluate h3 containment and never
//! asserts it.

use octet_verify::navigate::proof_region::Region;
use octet_verify::navigate::{H3PolygonSet, LocationProof, ProofRegion};
use octet_verify::verify::{verify, Status, VerifyOptions};

struct Vector {
    name: String,
    cells: Vec<u64>,
    point: (f64, f64),
    expect: Status,
}

fn vectors() -> Vec<Vector> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/test-vectors/h3-containment/vectors.json");
    let doc: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let hex64 = |v: &serde_json::Value| u64::from_str_radix(v.as_str().unwrap(), 16).unwrap();
    doc["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| {
            // The exact f64 bit patterns, so a boundary vertex survives parsing.
            let bits = v["point_f64_bits_hex"].as_array().unwrap();
            Vector {
                name: v["name"].as_str().unwrap().to_string(),
                cells: v["cell_ids_hex"].as_array().unwrap().iter().map(hex64).collect(),
                point: (f64::from_bits(hex64(&bits[0])), f64::from_bits(hex64(&bits[1]))),
                expect: match v["expect"].as_str().unwrap() {
                    "PASS" => Status::Pass,
                    "FAIL" => Status::Fail,
                    other => panic!("bad expect {other}"),
                },
            }
        })
        .collect()
}

fn region_contains(cells: &[u64], point: (f64, f64)) -> (Status, String) {
    let proof = LocationProof {
        claimed_region: Some(ProofRegion {
            region: Some(Region::H3PolygonSet(H3PolygonSet { cell_ids: cells.to_vec() })),
        }),
        ..Default::default()
    };
    let r = verify(
        &proof,
        &VerifyOptions {
            now_ms: 0,
            max_age_s: 300,
            hardware_pubkey: None,
            hw_key_source: "test",
            expect_region: None,
            expect_region_type: None,
            expect_region_contains: Some(point),
            expect_region_contains_height_m: None,
            session_nonce: None,
            require_session_binding: false,
            require_schema_v2: false,
            require_attestation: false,
            allow_unbound_app_attest: false,
            require_verdict: None,
            validation_window: None,
        },
    );
    let c = r.checks.iter().find(|c| c.name == "region-contains").expect("region-contains check");
    (c.status, c.detail.clone())
}

#[test]
fn vector_set_is_balanced_and_complete() {
    let v = vectors();
    assert_eq!(v.len(), 17, "expected 17 h3 containment vectors");
    let pass = v.iter().filter(|x| x.expect == Status::Pass).count();
    assert!(pass >= 5 && v.len() - pass >= 5, "need both PASS and FAIL cases");
}

#[cfg(feature = "h3")]
#[test]
fn h3_containment_matches_the_reference_vectors() {
    for v in vectors() {
        let (status, detail) = region_contains(&v.cells, v.point);
        assert_eq!(status, v.expect, "{}: {detail}", v.name);
    }
}

/// The malformed-set FAILs say why, so an operator can tell a bad region from a
/// point outside it.
#[cfg(feature = "h3")]
#[test]
fn malformed_sets_fail_with_a_reason() {
    let sf = (37.7749, -122.4194);
    let (s, d) = region_contains(&[], sf);
    assert_eq!(s, Status::Fail);
    assert!(d.contains("empty"), "{d}");
    let (s, d) = region_contains(&[0], sf);
    assert_eq!(s, Status::Fail);
    assert!(d.contains("not a valid H3 cell"), "{d}");
    let (s, d) = region_contains(&[0x8a283082800ffff], (f64::NAN, 0.0));
    assert_eq!(s, Status::Fail);
    assert!(d.contains("invalid point"), "{d}");
}

#[cfg(not(feature = "h3"))]
#[test]
fn lean_build_fails_closed_on_every_vector() {
    for v in vectors() {
        let (status, detail) = region_contains(&v.cells, v.point);
        assert_eq!(status, Status::Fail, "{}: lean build must never assert h3 containment", v.name);
        assert!(detail.contains("--features h3"), "{}: {detail}", v.name);
    }
}
